mapper.select:
        SELECT
            wpad.*,
            wp.id picking_pickingId,
            wp.task_order_number picking_pickingTaskOrderNumber,
            wo.id outbound_outboundId,
            wo.serial_number outbound_outboundSerialNumber
        FROM wms_picking_approve_detail wpad
        LEFT JOIN wms_picking_approve wpa ON wpa.id = wpad.picking_approve_id
        LEFT JOIN wms_picking wp ON wp.id = wpad.picking_id
        LEFT JOIN wms_outbound wo ON wo.id = wpad.out_id
        WHERE wpad.bool_delete_enum = 0 AND wpa.bool_delete_enum = 0
        AND wpa.review_status = 2
        
            AND wp.transact_status = #{transactStatus}
        
        
            AND wpad.picking_id = #{pickingId}
        
        
            AND wpad.picking_id IN
            
                #{pickingId}
            
        
        
            AND wpad.task_order_id = #{taskOrderId}
        
        
            AND wpad.picking_detail_material = #{material}
        
        
            AND wpad.picking_detail_thickness = #{thickness}
        
        
            AND wpad.picking_detail_specification = #{specification}
        
        
            AND wpad.bool_process = #{boolProcess}

SELECT wpad.picking_id as pickingId, SUM(IFNULL(wpad.picking_out_sum_quantity,0)) as pickingOutSumQuantity, SUM(IFNULL(wpad.picking_out_sum_mete,0)) as pickingOutSumMete, SUM(IFNULL(wpad.picking_out_sum_area,0)) as pickingOutSumArea, SUM(IFNULL(wpad.picking_out_sum_length,0)) as pickingOutSumLength FROM `wms_picking_approve` wpa LEFT JOIN `wms_picking_approve_detail` wpad on wpad.picking_approve_id = wpa.id and wpad.bool_delete_enum = 0 WHERE wpa.bool_delete_enum = 0 and wpa.review_status = 2 and wpad.picking_id = #{pickingId}
and wpad.picking_detail_material = #{material}
and wpad.picking_detail_thickness = #{thickness}
and wpad.picking_detail_specification = #{specification}
GROUP BY wpad.picking_id
